#!/usr/bin/env node
/**
 * P1631 D5: bundles the Clarify drafting prompt into supabase/functions/clarify-draft/clarify-prompt.generated.ts, so the
 * edge function (which cannot read the repo at run time) carries ONE copy of each source:
 *   .claude/commands/slava/disagreement/prepare.md   (front matter dropped)
 *   docs/story-point-model.md
 *   supabase/functions/clarify-draft/clarify-adapter.md    (the live-conversation overrides, last so they win)
 *
 * Usage:  node scripts/build-clarify-prompt.mjs          writes the generated file
 *         node scripts/build-clarify-prompt.mjs --check  exits 1 when the file differs from a fresh build
 * src/tests/p1631-clarify-prompt-bundle.test.ts fails when the generated file is stale.
 */
import { createHash } from 'node:crypto';
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
export const SOURCES = [
  '.claude/commands/slava/disagreement/prepare.md',
  'docs/story-point-model.md',
  'supabase/functions/clarify-draft/clarify-adapter.md',
];
export const OUT = 'supabase/functions/clarify-draft/clarify-prompt.generated.ts';

const sha = (s) => createHash('sha256').update(s).digest('hex').slice(0, 12);

function stripFrontMatter(text) {
  return text.startsWith('---\n') ? text.slice(text.indexOf('\n---\n', 4) + 5).replace(/^\n+/, '') : text;
}

/** The full text of the generated file for the sources as they stand now. */
export function buildClarifyPromptFile(root = ROOT) {
  const parts = SOURCES.map((rel) => {
    const raw = readFileSync(join(root, rel), 'utf8');
    return { rel, raw, text: (rel.endsWith('prepare.md') ? stripFrontMatter(raw) : raw).trim() };
  });
  const prompt = parts.map((p) => p.text).join('\n\n---\n\n') + '\n';
  const header = [
    '// GENERATED by scripts/build-clarify-prompt.mjs. Do not edit: change a source and rebuild.',
    ...parts.map((p) => `// source ${p.rel} sha256:${sha(p.raw)}`),
    '',
  ].join('\n');
  return `${header}export const CLARIFY_SYSTEM_PROMPT = ${JSON.stringify(prompt)};\n`;
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const fresh = buildClarifyPromptFile();
  const target = join(ROOT, OUT);
  if (process.argv.includes('--check')) {
    let current = '';
    try { current = readFileSync(target, 'utf8'); } catch { /* missing counts as stale */ }
    if (current !== fresh) {
      console.error(`${OUT} is stale: run node scripts/build-clarify-prompt.mjs`);
      process.exit(1);
    }
    console.log(`${OUT} is current`);
  } else {
    writeFileSync(target, fresh);
    console.log(`wrote ${OUT} (${fresh.length} bytes)`);
  }
}
